-- Batch update templates 5-13 with full user-provided content.
UPDATE public.prd_templates
SET description = $desc$Structured document for investigating, diagnosing, and fixing a bug. Covers symptoms, reproduction, root cause analysis, proposed fix, and verification — useful for complex bugs that need clear documentation.$desc$,
    structure = $json${"instructions": "Write this like an engineering investigation report — factual, precise, and evidence-based. Reproduction steps should be exact (click this, type that, see this error). Root cause analysis should trace the actual code path that fails, not speculate. The proposed fix should be specific enough for an AI coding assistant or engineer to implement directly. Include what NOT to do if there are tempting but wrong fixes. The test plan should verify the fix works and confirm nothing else broke.", "sections": [{"name": "Bug Summary", "guidelines": "### Overview\nWhat is happening in 1-2 sentences — describe the broken behavior, not the fix.\n\n### Metadata\n- Severity: Critical / High / Medium / Low\n- Affected users: Percentage or count, and which segments\n- First observed: Date and how it was discovered\n- Environment: Production / Staging / Both\n- Error tracking: Link to Sentry issue, LogRocket session, or relevant logs\n\n### Business Impact\nWhat is the cost of this bug remaining unfixed? Revenue loss, blocked users, trust erosion, support load, etc."}, {"name": "Reproduction Steps", "guidelines": "Exact numbered steps to reproduce, starting from a clean state.\n\n### Steps\n1. Go to [URL/page]\n2. Log in as [role/account type]\n3. Click [element] / Enter [input]\n4. Observe [broken behavior]\n\n### Environment Details\n- Browser/device: Chrome 120 on macOS, Safari on iOS 17, etc.\n- Account type: Admin, free user, new signup, etc.\n- Required data: Specific data conditions needed to trigger the bug\n- Frequency: Always reproducible / Intermittent (describe conditions that increase likelihood)\n- Timing: Any time-dependent or sequence-dependent factors"}, {"name": "Expected vs. Actual Behavior", "guidelines": "### Expected Behavior\nWhat SHOULD happen according to the spec, design, or previous working state. Reference the source of truth (Figma, PRD, previous release).\n\n### Actual Behavior\nWhat ACTUALLY happens. Be precise:\n- Visual: What the user sees (include screenshots)\n- Console: Any errors in browser console or server logs\n- Network: Failed requests, unexpected responses, status codes\n- Data: Any data corruption, missing records, or incorrect state\n\n### What Still Works\nNote any related functionality that is NOT broken — this helps narrow the root cause."}, {"name": "Root Cause Analysis", "guidelines": "### Investigation Trail\nWhat was checked and ruled out during debugging:\n1. Checked [hypothesis A] → Ruled out because [evidence]\n2. Checked [hypothesis B] → Found the issue here\n\n### Root Cause\n- File: Exact file path and function/line\n- What happens: Trace the code path from user action to failure\n- Why it fails: The specific logic error, missing check, race condition, or data issue\n- When it was introduced: Regression from [PR/commit]? Always existed? Data-dependent?\n\n### Contributing Factors\nAnything that made this bug possible: missing tests, unclear spec, tech debt, etc."}, {"name": "Proposed Fix", "guidelines": "### Recommended Approach\n- Files to modify: List each file and the change needed\n- Logic change: Describe the fix at a code-concept level\n- Why this is correct: Explain why this fix addresses the root cause\n\n### Alternative Approaches\nIf there are other ways to fix this:\n- Option B: Description, with pros/cons vs. recommended approach\n- Option C: Description, with pros/cons\n\n### Risks\n- Could this fix break anything else?\n- Any performance implications?\n- Does this need a database migration or data backfill?"}, {"name": "Test Plan", "guidelines": "### Manual Verification\n1. Follow reproduction steps → Bug no longer occurs\n2. [Additional manual check]\n3. [Edge case verification]\n\n### Automated Tests to Write\n- Unit test: Test the specific function/logic that was fixed\n- Integration test: Test the API endpoint or data flow end-to-end\n- E2E test: Test the user flow if this is a critical path\n### Regression Checks\n- Verify [related feature A] still works correctly\n- Verify [related feature B] still works correctly\n- Monitor error tracking (Sentry) for 24-48 hours post-deploy"}, {"name": "Prevention", "guidelines": "How to prevent this class of bug from recurring.\n\n### Immediate Actions\n- Add specific test coverage: [describe exact test]\n- Add input validation: [describe exact check]\n- Add monitoring/alerting: [describe exact alert]\n\n### Systemic Improvements\n- Type safety: [specific TypeScript strictness or type guard]\n- Code review checklist: [specific item to add]\n- Architecture change: [if applicable, describe structural fix]\n\n### Documentation\n- Update relevant docs or runbooks\n- Add to known issues or team knowledge base"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Bug Investigation & Fix Plan$name$;

UPDATE public.prd_templates
SET description = $desc$This template provides a comprehensive structure for analyzing and reporting on competitors, covering company background, product offerings, market positioning, and strategic insights.$desc$,
    structure = $json${"instructions": "Go beyond surface-level feature comparison. Include specific pricing, positioning gaps, and strategic differences. Be honest about your own product's weaknesses relative to competitors. Customer sentiment should come from real reviews and data sources. Every insight should connect to an actionable product or strategy recommendation.", "sections": [{"name": "Company Profiles", "guidelines": "Background on each competitor being analyzed.\n\n### Format for Each Competitor\n[Competitor Name]\n- Overview: What they do, company size, funding stage, headquarters\n- Founded: Year and brief history\n- Revenue/Funding: Publicly available financial signals\n- Key products: Their main offerings and target market\n- Leadership: Notable executives and their background\n- Recent moves: Acquisitions, pivots, major launches in the last 12 months\n\n### Your Company (for comparison)\nBrief summary of your own positioning to anchor the analysis."}, {"name": "Product Comparison", "guidelines": "Feature-by-feature analysis against your product.\n\n### Feature Matrix\n| Feature | Your Product | Competitor A | Competitor B | Competitor C |\n|---------|-------------|-------------|-------------|-------------|\n| [Feature 1] | ✓ / ✗ / Partial | ✓ / ✗ / Partial | ✓ / ✗ / Partial | ✓ / ✗ / Partial |\n| [Feature 2] | ... | ... | ... | ... |\n\n### Deep Dives\nFor the 3-5 most important features, compare in detail:\n- Your approach: How you do it\n- Their approach: How they do it\n- User impact: Which approach is better for users and why\n\n### Innovation & Technology\n- Unique capabilities each competitor has\n- Technology investments (AI/ML, platform, infrastructure)\n- R&D signals (hiring, patents, open source)"}, {"name": "SWOT Analysis", "guidelines": "Strengths, weaknesses, opportunities, and threats for each competitor.\n\n### Format for Each Competitor\n[Competitor Name]\n\n| | Helpful | Harmful |\n|---|---------|--------|\n| Internal | Strengths: [List] | Weaknesses: [List] |\n| External | Opportunities: [List] | Threats: [List] |\n\n### Your SWOT (Honest Assessment)\nApply the same framework to your own product — be candid about weaknesses.\n\n### Key Insights\n- Where competitors are strongest relative to you\n- Where you have clear advantages\n- Where the market has unmet needs that nobody serves well"}, {"name": "Market Positioning & Pricing", "guidelines": "How competitors position themselves and price their products.\n\n### Positioning Map\nDescribe where each competitor sits along key dimensions:\n- Axis 1: e.g., Simple ←→ Enterprise-grade\n- Axis 2: e.g., Affordable ←→ Premium\n\n### Brand Perception\nFor each competitor:\n- How the market perceives them (trusted, innovative, cheap, complex)\n- Key messaging themes from their website and marketing\n- Customer sentiment from reviews (G2, Capterra, Reddit, Twitter)\n\n### Pricing Comparison\n| | Free Tier | Entry Price | Mid Tier | Enterprise |\n|---|-----------|-------------|----------|------------|\n| Your Product | [details] | [price] | [price] | [price] |\n| Competitor A | [details] | [price] | [price] | [price] |\n### Customer Acquisition\n- Primary channels each competitor uses (PLG, sales-led, partnerships)\n- Estimated marketing spend or presence\n- Retention strategies: loyalty programs, lock-in, switching costs"}, {"name": "Strategic Insights", "guidelines": "Actionable conclusions that should inform your strategy.\n\n### Key Takeaways\n3-5 most important insights from the analysis:\n1. Insight: [Finding] → Implication: [What to do about it]\n2. Insight: [Finding] → Implication: [What to do about it]\n\n### Competitive Advantages to Protect\n- Your strongest differentiators that competitors would struggle to replicate\n- How to strengthen and communicate these advantages\n\n### Vulnerabilities to Address\n- Areas where competitors clearly outperform you\n- Specific actions to close the gap, with priority and timeline\n\n### Market Gaps\n- Unmet needs that no competitor serves well\n- Opportunity to differentiate or create a new category\n\n### Competitive Response Plan\n- How to respond if [Competitor A] launches [specific feature]\n- How to respond if [Competitor B] undercuts on price\n- Signals to monitor (job postings, funding, product updates)"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Competitive Analysis Report$name$;

UPDATE public.prd_templates
SET description = $desc$A comprehensive template for mapping out and improving the customer journey, including customer personas, journey stages, opportunities for improvement, and an action plan.$desc$,
    structure = $json${"instructions": "Map the actual customer experience, not the idealized version. Include emotional states at each stage — frustration, confusion, delight. Touchpoints should be specific (e.g., \"order confirmation email\" not \"communication\"). Opportunities for improvement should connect directly to observed pain points with clear prioritization. Be honest about where the experience breaks down.", "sections": [{"name": "Customer Persona", "guidelines": "A detailed profile of the primary customer whose journey you are mapping.\n\n### Demographics\n- Age, role, location, income level, company size\n\n### Behavior\n- Buying habits, brand preferences, digital behavior, tool usage\n\n### Needs & Goals\n- What they are trying to accomplish\n- What success looks like for them\n\n### Challenges\n- Pain points and frustrations they face daily\n- What prevents them from reaching their goals\n\n### Preferred Channels\n- How they prefer to communicate: email, chat, phone, self-serve\n- Where they spend time: social media, communities, publications"}, {"name": "Journey Stages", "guidelines": "The customer's experience mapped across each stage of their relationship with your product.\n\n### Awareness\n- Actions: How they first discover your product\n- Feelings: Curiosity, skepticism, excitement\n- Touchpoints: Ads, content, word of mouth, social media\n- Key question: 'Is this relevant to me?'\n\n### Consideration\n- Actions: Comparing you against alternatives\n- Feelings: Evaluation, uncertainty, hope\n- Touchpoints: Website, demos, reviews, free trial\n- Key question: 'Is this better than what I have?'\n\n### Decision\n- Actions: Making the purchase/signup decision\n- Feelings: Confidence or hesitation\n- Touchpoints: Pricing page, sales call, checkout flow\n- Key question: 'Is this worth the investment?'\n\n### Onboarding & First Value\n- Actions: Setting up, learning, first success\n- Feelings: Excitement, confusion, accomplishment\n- Touchpoints: Onboarding flow, docs, support, email sequences\n- Key question: 'Can I get value quickly?'\n\n### Retention\n- Actions: Regular usage, deeper adoption\n- Feelings: Satisfaction, habit formation, or frustration\n- Touchpoints: Product UI, feature updates, support\n- Key question: 'Is this still worth it?'\n\n### Advocacy\n- Actions: Recommending to others, writing reviews\n- Feelings: Pride, loyalty, community belonging\n- Touchpoints: Referral programs, communities, social sharing\n- Key question: 'Am I proud to recommend this?'"}, {"name": "Pain Points & Moments of Truth", "guidelines": "Specific points where the experience breaks down or delights.\n### Pain Points\nFor each pain point:\n- Stage: Which journey stage\n- Pain: What goes wrong\n- Severity: Frustrating / Painful / Causes churn\n- Frequency: How often it occurs\n- Evidence: Data, quotes, or support tickets that prove this\n\n### Moments of Truth\nCritical interactions that disproportionately influence the customer's perception:\n- First impression: The initial experience that sets expectations\n- Aha moment: When the customer first realizes the value\n- Recovery moment: How you handle things when they go wrong\n\nThese are the highest-leverage points to improve."}, {"name": "Opportunities for Improvement", "guidelines": "Gaps and possibilities identified from mapping the journey.\n\n### Unmet Needs\n- Needs the product doesn't address yet\n- Features competitors offer that you don't\n- Workarounds customers have built\n\n### Experience Gaps\n- Stages where the experience is weakest\n- Handoffs between channels that feel broken\n- Information customers need but can't easily find\n\n### Innovation Areas\n- Where introducing new features or processes could transform the experience\n- Technology-enabled improvements (AI, automation, personalization)\n- Areas where simplification would have outsized impact\n\n### Quick Wins\n- Low-effort, high-impact improvements that can ship fast"}, {"name": "Action Plan", "guidelines": "Concrete initiatives to improve the journey, organized by priority.\n\n### Immediate (This Quarter)\nFor each initiative:\n- Initiative: [Name]\n- Journey stage: [Which stage it improves]\n- Expected impact: [Which pain point it addresses and metric it moves]\n- Owner: [Who is responsible]\n- Effort: Small / Medium / Large\n\n### Near-Term (Next 2 Quarters)\n- Larger initiatives requiring design and engineering investment\n- Pilot programs to test before full rollout\n\n### Long-Term (6-12 Months)\n- Structural changes to the product or organization\n- Platform or infrastructure investments\n\n### Success Metrics\n- How you will measure whether the journey is actually improving\n- Baseline measurements to take now\n- Review cadence and accountability"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Customer Journey Map$name$;

UPDATE public.prd_templates
SET description = $desc$Plan your data model, relationships, indexes, and migrations before AI generates them. Prevents costly rework by thinking through entities, access patterns, and constraints upfront.$desc$,
    structure = $json${"instructions": "Write this as a precise technical reference for building the database. Entity definitions should list actual field names with types (e.g., id: uuid, email: text, createdAt: timestamptz). Relationships should be explicit about cardinality and foreign keys. Access patterns should describe real queries the app will run. Be opinionated about index choices and explain the tradeoffs. Use the user's stated database technology (Postgres, MySQL, MongoDB, etc.).", "sections": [{"name": "Overview & Goals", "guidelines": "What data this system manages and the key design priorities.\n\n### Database Choice\n- Technology: PostgreSQL, MySQL, MongoDB, SQLite, etc.\n- Hosting: Neon, Supabase, PlanetScale, self-hosted, etc.\n- Rationale: Why this database fits the use case\n\n### Design Priorities\n- Read vs. write heavy: Which matters more?\n- Consistency model: Strong consistency vs. eventual\n- Normalization: Normalized, denormalized, or hybrid\n- Scale expectations: Expected row counts and query volume"}, {"name": "Core Entities", "guidelines": "Define every table or collection with all fields.\n\n### Format\n\nTableName\n- id: uuid (PK, default: gen_random_uuid())\n- fieldName: type (constraints)\n- fieldName: type (nullable, default: value)\n- createdAt: timestamptz (default: now())\n- updatedAt: timestamptz\n\n\n### Field Annotations\n- PK: Primary key\n- FK: Foreign key (reference: Table.field)\n- UQ: Unique constraint\n- IDX: Indexed\n- Mark required vs. nullable fields explicitly\n\nGroup related entities together (e.g., User entities, Content entities, Billing entities)."}, {"name": "Relationships & Constraints", "guidelines": "### Relationship Map\nList every relationship between entities:\n- One-to-one: User → UserProfile\n- One-to-many: User → Post (user has many posts)\n- Many-to-many: User ↔ Organization (via Membership table)\n\n### Foreign Key Behavior\nFor each FK, specify:\n- ON DELETE: CASCADE, SET NULL, RESTRICT, or NO ACTION\n- ON UPDATE: CASCADE or NO ACTION\n\n### Constraints\n- Unique constraints: e.g., (orgId, email) must be unique together\n- Check constraints: e.g., price > 0, status IN ('active', 'archived')\n- Business rules: Any logic enforced at the DB level"}, {"name": "Indexes & Performance", "guidelines": "### Required Indexes\nFor each index beyond primary keys:\n- Table.column(s): Index type, which query it supports\n\n### Example\n\nPost.authorId — B-tree, for filtering posts by author\nPost.(status, createdAt) — Composite, for listing active posts sorted by date\nPost.title — GIN (trigram), for full-text search\n\n\n### Performance Considerations\n- Queries expected to be slow or complex\n- N+1 risks and how to prevent them (eager loading, joins)\n- Pagination strategy (cursor-based vs. offset)\n- Caching approach for frequently read data"}, {"name": "Access Patterns", "guidelines": "Describe the most common queries the application will run.\n\n### Format\n\nPattern: List all projects for a user\nQuery: SELECT * FROM Project WHERE ownerId = ? ORDER BY createdAt DESC\nFrequency: Very high (every page load)\nIndexes used: Project.ownerId\n\n\n### Categories\n- High-frequency reads: Dashboard, lists, lookups\n- Writes: Creates, updates, deletes\n- Complex queries: Aggregations, reports, search\n- Background jobs: Scheduled queries, batch processing"}, {"name": "Migration Plan", "guidelines": "### Migration Tool\n- Tool: Prisma Migrate, Drizzle Kit, Knex, raw SQL, etc.\n- Workflow: How migrations are created, reviewed, and applied\n\n### Seed Data\n- Development seed data for testing\n- Required production seed data (roles, default settings, etc.)\n\n### Evolution Strategy\n- Approach to zero-downtime migrations in production\n- Column rename/removal process (add new → migrate data → remove old)\n- Data backfill procedures for new required columns"}, {"name": "Security & Privacy", "guidelines": "### Sensitive Data Inventory\nIdentify every field containing sensitive data:\n- PII: email, name, phone, address\n- Credentials: password hashes, API keys, tokens\n- Financial: payment info, billing addresses\n\n### Protection Measures\n- Encryption at rest: Database-level or column-level\n- Hashing: Which fields (e.g., passwords with bcrypt/argon2)\n- Row-level security: If applicable, describe RLS policies\n\n### Compliance\n- Data retention: How long data is kept, auto-deletion policies\n- Right to deletion: Process for GDPR/CCPA delete requests\n- Audit logging: Which operations are logged"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Database Schema Design$name$;

UPDATE public.prd_templates
SET description = $desc$A single-feature spec optimized for handing to an AI coding agent. Defines exactly what to build, acceptance criteria, edge cases, and files to touch — everything needed for a focused implementation session.$desc$,
    structure = $json${"instructions": "Write this as a tight, actionable spec for one feature that an AI coding assistant can execute in a single session. Be extremely specific about acceptance criteria — each one should be independently testable. The technical approach should name exact files, functions, and components to create or modify. Edge cases should cover error states, empty states, loading states, and permission boundaries. Skip philosophy and context-setting — go straight to what needs to be built.", "sections": [{"name": "Feature Summary", "guidelines": "What this feature does in 1-2 sentences, why it matters, and who uses it.\n\n### Scope\n- In scope: What is part of this feature\n- Out of scope: What is explicitly NOT included\n- Prerequisites: Features or infrastructure that must exist first\n- Depends on: APIs, data, or services this feature needs"}, {"name": "Acceptance Criteria", "guidelines": "Numbered list of specific, testable criteria. Each should be independently verifiable.\n### Must-Have (P0)\n1. User can [action] and sees [result]\n2. System [validates/enforces] [rule]\n3. [State change] persists after page refresh\n\n### Should-Have (P1)\n4. [Secondary capability]\n5. [Edge case handling]\n\n### Nice-to-Have (P2)\n6. [Polish item]\n\nEach criterion should be a concrete behavior, not a vague quality ('User can filter by date range and sees results update within 500ms' not 'Filtering works well')."}, {"name": "User Flow", "guidelines": "Step-by-step walkthrough of the user interaction.\n\n### Happy Path\n1. Entry point: User navigates to [page] and sees [initial state]\n2. Action: User clicks [element] / fills [form] / selects [option]\n3. Feedback: System shows [loading state / optimistic update]\n4. Result: User sees [success state / new content / confirmation]\n5. Next step: User can now [follow-up action]\n\n### Alternate Paths\n- Path B: If user [alternative action], then [what happens]\n- Path C: If user [cancels/goes back], then [what happens]\n\nNote specific UI components and layout at each step."}, {"name": "Edge Cases & Error States", "guidelines": "Everything that could go wrong or deviate from the happy path.\n\n### Input Validation\n- Empty/missing required fields → [error message]\n- Invalid format (email, URL, etc.) → [error message]\n- Input too long/short → [error message]\n\n### System Errors\n- Network failure → [retry behavior, offline message]\n- Server error (500) → [error UI, retry option]\n- Timeout → [timeout message, recovery]\n\n### Permission & State\n- Unauthorized access → [redirect, error message]\n- Stale data / concurrent edit → [conflict resolution]\n- Empty state (no data yet) → [empty state UI, CTA]\n- Rate limited → [throttle message]"}, {"name": "Technical Approach", "guidelines": "Implementation strategy — specific enough to build from, but not actual code.\n\n### Files to Create/Modify\n- src/components/[Feature]/ — New component(s)\n- src/app/api/[route]/ — New or modified API endpoint\n- src/lib/[module].ts — Business logic\n- prisma/schema.prisma — Schema changes (if any)\n\n### Data Flow\n1. UI triggers [action]\n2. Calls [API endpoint / server action]\n3. Validates input with [schema]\n4. Reads/writes [database table]\n5. Returns [response shape]\n6. UI updates [state / cache]\n\n### New Dependencies\nList any new packages needed with justification."}, {"name": "Dependencies & Risks", "guidelines": "### Dependencies\n- Upstream: APIs or features this depends on\n- Downstream: What depends on this feature\n- External: Third-party services required\n\n### Technical Risks\n- Performance: Will this be slow at scale? What is the expected query volume?\n- Security: Any new attack surface (user input, file upload, etc.)?\n- Data integrity: Risk of data corruption or loss?\n\n### Rollout Strategy\n- Feature flag: Is one needed?\n- Staged rollout: Internal → beta → GA?\n- Rollback plan: How to revert if something goes wrong"}, {"name": "Test Plan", "guidelines": "### Manual Testing\nStep-by-step QA checklist:\n1. [Test the happy path end to end]\n2. [Test each edge case from above]\n3. [Test on mobile / different browsers if relevant]\n\n### Automated Tests\n- Unit tests: Business logic, validation, utilities\n- Integration tests: API endpoints with database\n- E2E tests: Critical user flow (if warranted)\n\n### Regression Checks\n- Verify [related feature A] still works\n- Verify [related feature B] still works\n- Check error tracking (Sentry) for new errors after deploy"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Feature Implementation Spec$name$;

UPDATE public.prd_templates
SET description = $desc$Strategic plan for launching the product, including marketing, sales, and operational activities.$desc$,
    structure = $json${"instructions": "Focus on actionable, time-bound activities with clear owners and success criteria. Pricing strategy should include competitive context and justification. Promotional plans should specify channels with expected outcomes. The overall plan should be executable by the team, not aspirational marketing fluff.", "sections": [{"name": "Executive Summary", "guidelines": "The entire GTM strategy in one paragraph. A busy executive should be able to read this and know the plan.\n### Include\n- What you are launching\n- Who you are targeting\n- When you are launching\n- How you will reach them\n- Goal for the first 90 days (one key metric)"}, {"name": "Market Analysis", "guidelines": "The landscape you are launching into.\n\n### Market Size\n- TAM: Total addressable market\n- SAM: Serviceable addressable market\n- SOM: Serviceable obtainable market (realistic near-term target)\n\n### Target Segments\nFor each segment:\n- Who they are: Demographics, company size, role\n- Why they buy: Primary motivation and trigger event\n- Where they are: Channels, communities, publications they trust\n- Current solution: What they use today and why it's insufficient\n\n### Competitive Landscape\nKey competitors and your differentiation against each."}, {"name": "Product Positioning", "guidelines": "How the product will be perceived in the market.\n\n### Positioning Statement\nFor [target customer] who [need/pain point], [product name] is a [category] that [key benefit]. Unlike [alternatives], it [key differentiator].\n\n### Messaging Hierarchy\n- Primary message: The one thing everyone should remember\n- Supporting messages: 3 proof points that back up the primary message\n- Proof points: Data, testimonials, or demos that make it believable\n\n### Tone & Voice\nHow the product should feel in all communications: technical, approachable, premium, playful, etc."}, {"name": "Pricing Strategy", "guidelines": "How the product is priced and why.\n\n### Pricing Model\n- Model type: Freemium, free trial, subscription, usage-based, one-time, etc.\n- Tiers: What each tier includes and who it's for\n- Price points: Specific numbers with justification\n\n### Competitive Context\n- How your pricing compares to alternatives\n- Price anchoring strategy (positioned as premium, value, or disruptive)\n\n### Metrics\n- Target conversion rate: Free → paid\n- Target ARPU: Average revenue per user\n- Expansion path: How users upgrade over time"}, {"name": "Promotional Plan", "guidelines": "How you will generate awareness and demand.\n\n### Launch Channels\nFor each channel:\n- Channel: e.g., Product Hunt, Twitter/X, email, content marketing, paid ads\n- Tactic: Specific action (e.g., 'Launch on PH with 50 pre-committed upvoters')\n- Timeline: When this happens relative to launch\n- Owner: Who is responsible\n- Budget: Estimated spend (if any)\n\n### Content Plan\n- Launch blog post / announcement\n- Demo video or product walkthrough\n- Customer stories or case studies\n- Social media content calendar\n\n### PR & Partnerships\n- Press outreach targets\n- Partnership or co-marketing opportunities"}, {"name": "Sales Strategy", "guidelines": "How the product will be sold.\n\n### Sales Motion\n- Self-serve: Users sign up and convert on their own\n- Sales-assisted: Inbound leads get a demo or call\n- Outbound: Proactive outreach to target accounts\n- Hybrid: Combination (describe the trigger for each)\n\n### Sales Enablement\n- One-pager or pitch deck\n- Demo script and environment\n- Objection handling guide\n- Competitive battlecard\n\n### Partner & Channel Sales\nAny indirect sales channels: resellers, integrations marketplace, agency partners."}, {"name": "Success Metrics", "guidelines": "How you will know the launch is working.\n\n### 30-Day Targets\n- Awareness: Website visits, signups, waitlist additions\n- Activation: Users who complete onboarding or key action\n- Revenue: MRR, deals closed, or conversion rate\n\n### 90-Day Targets\n- Retention: Day-30 and Day-60 retention rates\n- Growth: Month-over-month growth rate\n- Satisfaction: NPS, CSAT, or qualitative feedback themes\n\n### Tracking\n- Which tools are used (analytics, CRM, support)\n- Who reviews metrics and how often\n- What triggers a pivot or escalation if targets are missed"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Go-to-Market Plan$name$;

UPDATE public.prd_templates
SET description = $desc$Spec for a marketing or product landing page: hero, value props, social proof, CTAs, and design direction. Hand this to an AI tool like v0, Cursor, or Lovable to generate a polished landing page.$desc$,
    structure = $json${"instructions": "Write this as a creative brief that could be handed directly to a designer or AI page builder. Be specific about copy — write actual headlines, not placeholders. Value propositions should be benefit-focused, not feature-focused. Social proof should feel authentic. Design direction should reference specific visual styles, color palettes, or reference sites rather than vague adjectives like 'modern' or 'clean.' The page should have a clear conversion narrative from top to bottom.", "sections": [{"name": "Page Goal & Audience", "guidelines": "### Conversion Goal\nThe single primary action you want visitors to take: sign up, buy, book a demo, join waitlist, download, etc.\n\n### Target Visitor\n- Traffic source: Where they come from (paid ad, organic search, Product Hunt, referral, social)\n- Awareness level: What they already know about you\n- Key question: The #1 thing on their mind when they land\n- Primary objection: What might stop them from converting\n\nThis profile shapes every section below — the page should feel like a direct answer to this visitor."}, {"name": "Hero Section", "guidelines": "The first thing visitors see — it must answer three questions instantly: What is this? Who is it for? Why should I care?\n\n### Copy\n- Headline: 8 words or fewer, benefit-driven (not clever — clear)\n- Subheadline: 1-2 sentences expanding on the value proposition\n- CTA button: Exact button text (e.g., 'Start free trial' not 'Submit')\n\n### Visual\n- Hero image/visual: Product screenshot, demo video, illustration, or animation\n- Layout: Full-width, split (text left / visual right), centered, etc.\n- Above the fold: Everything visible before scrolling"}, {"name": "Value Propositions", "guidelines": "3-4 key benefits written from the user's perspective — what they GET, not what the product HAS.\n\n### Format for Each\n- Headline: 5-8 words, benefit-focused\n- Description: 1-2 sentences explaining how the product delivers this benefit\n- Visual: Icon suggestion, illustration, or screenshot\n\n### Example\n- Ship 10x faster — AI handles the boilerplate so you focus on what makes your product unique. No more copy-pasting patterns between projects.\n\nOrder from most compelling to least. Address the visitor's top concerns from the audience section above."}, {"name": "Social Proof", "guidelines": "What builds trust and credibility on this page. Be specific — vague praise doesn't convert.\n\n### Options (pick 2-4)\n- Customer testimonials: Real quotes with name, title, company, and photo\n- Logo bar: Companies/brands that use the product\n- Usage stats: '10,000+ teams,' '2M documents created,' etc.\n- Press mentions: 'Featured in TechCrunch, Product Hunt #1 of the day'\n- Case study snippet: 'Company X increased conversion by 40%'\n- Awards/badges: G2, Product Hunt, industry awards\n\nOrder by persuasiveness. Lead with whatever is strongest."}, {"name": "Feature Showcase", "guidelines": "3-5 key features that demonstrate HOW the product delivers the value props above.\n\n### Format for Each\n- Headline: Benefit-oriented, not technical ('See changes in real time' not 'WebSocket integration')\n- Description: 2-3 sentences on how it works and why it matters\n- Visual: Screenshot, GIF, short video, or illustration\n- Layout: Alternating left/right, tabbed showcase, or interactive demo\n\nOrder from most impressive to least. Each feature should build confidence that the product actually works."}, {"name": "CTA & Conversion", "guidelines": "### Primary CTA\n- Button copy: Exact text (action-oriented: 'Start building free' not 'Get started')\n- Form fields: Only what is absolutely required (email? name + email? just a button?)\n- Placement: After hero, after features, sticky footer, etc.\n\n### Secondary CTA\n- For hesitant visitors: 'Watch demo,' 'See pricing,' 'Talk to sales'\n\n### Trust Builders\n- Risk reducers: 'No credit card required,' '14-day free trial,' 'Cancel anytime'\n- Pricing preview: Show pricing or 'Free for up to X users'\n- Urgency (if authentic): 'Early access pricing,' 'Limited beta spots'"}, {"name": "Design Direction", "guidelines": "### Visual Style\n- Color palette: Primary, secondary, accent (hex codes or descriptive: 'dark navy + electric blue accents')\n- Typography: Sans-serif modern, serif editorial, monospace tech, etc.\n- Spacing: Dense/information-rich vs. spacious/premium\n- Vibe: Minimal, playful, corporate, developer-focused, luxury, etc.\n\n### References\nList 1-3 existing sites whose visual style to emulate and what specifically to borrow from each.\n\n### Brand Assets\n- Logo, brand fonts, brand colors that must be used\n- Existing design system or component library\n\n### Responsive\n- Mobile-first or desktop-first\n- Key mobile adaptations (collapsed nav, stacked layout, etc.)\n- Animation and interaction preferences (subtle or expressive)"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Landing Page Brief$name$;

UPDATE public.prd_templates
SET description = $desc$Generate a list of objectives and key results based on your product and business goals$desc$,
    structure = $json${"instructions": "Write objectives that are ambitious but achievable within the stated timeframe. Key results must be specific and measurable with concrete numbers — avoid vague outcomes like \"improve\" or \"increase.\" Each initiative should clearly connect to its parent key result. Use the user's actual context for timelines, not generic placeholders. Risks should be realistic and paired with actionable mitigations.", "sections": [{"name": "Objective", "guidelines": "Clearly state the main goal you want to achieve. This should be ambitious but achievable.\n\n### Guidelines\n- Qualitative, not quantitative — objectives describe the destination, key results measure progress\n- Inspiring but grounded — should motivate the team and feel attainable\n- Time-bound — specify the quarter or timeframe\n- Aligned — should connect to company-level strategy\n\n### Example\n'Become the go-to solution for small teams managing customer feedback' (Q2 2026)"}, {"name": "Key Results", "guidelines": "Measurable outcomes that indicate progress toward the objective. Aim for 3-5 per objective.\n\n### Format\nKR[#]: [Verb] [metric] from [baseline] to [target] by [date]\n\n### Guidelines\n- Each KR must be specific and measurable with a concrete number\n- Include the current baseline — you can't measure progress without a starting point\n- Mix leading indicators (actions) and lagging indicators (outcomes)\n- Set a stretch target (70% achievement = good) not a sandbagged one\n\n### Example\n- KR1: Increase weekly active users from 2,000 to 5,000\n- KR2: Achieve NPS score of 50+ (currently 32)\n- KR3: Reduce average onboarding time from 15 min to 5 min"}, {"name": "Initiatives", "guidelines": "High-level projects or workstreams that will drive the key results. 1-3 initiatives per key result.\n\n### Format\nFor each initiative:\n- Initiative: What you will do\n- Drives KR: Which key result(s) this supports\n- Owner: Who is responsible\n- Effort estimate: T-shirt size (S/M/L/XL)\n\n### Guidelines\n- Initiatives are the 'how' — they connect the measurable KRs to actual work\n- Each should be concrete enough to staff and schedule\n- If an initiative doesn't clearly drive a KR, question whether it belongs"}, {"name": "Alignment", "guidelines": "How these OKRs connect to the bigger picture.\n\n### Company Alignment\n- Which company-level objective(s) these support\n- How success here contributes to overall business goals\n\n### Cross-Team Dependencies\n- Other teams whose OKRs overlap or depend on yours\n- Shared key results or handoff points\n- Potential conflicts to resolve early\n\n### Strategic Context\nWhy these objectives matter NOW — what market conditions, customer feedback, or business priorities make this the right focus."}, {"name": "Key Stakeholders", "guidelines": "Who is responsible for each key result and initiative.\n\n### Format\n| Role | Person | Responsibility |\n|------|--------|----------------|\n| OKR Owner | [Name] | Overall accountability for the objective |\n| KR1 Lead | [Name] | Drives KR1, reports progress weekly |\n| KR2 Lead | [Name] | Drives KR2, reports progress weekly |\n\n### Escalation Path\nWho makes the call when trade-offs are needed between competing KRs or when a KR is off-track."}, {"name": "Timeline & Checkpoints", "guidelines": "When results are expected and how progress is tracked.\n### Milestones\n- Week 2: [Early signal or setup milestone]\n- Month 1: [First meaningful progress checkpoint]\n- Mid-quarter: [Halfway check — are we on track?]\n- End of quarter: [Final measurement and scoring]\n\n### Cadence\n- Weekly: Quick status update (on track / at risk / off track)\n- Bi-weekly or monthly: Deeper review with stakeholders\n- End of quarter: Full scoring and retrospective"}, {"name": "Risks and Mitigations", "guidelines": "What could prevent you from hitting these OKRs.\n\n### Format\nFor each risk:\n- Risk: What could go wrong\n- Likelihood: Low / Medium / High\n- Impact: Which KR(s) would be affected\n- Mitigation: What you'll do to prevent or reduce this risk\n- Contingency: What you'll do if it happens anyway\n\n### Common OKR Risks\n- Dependency on another team that has different priorities\n- Metric measurement is harder than expected (no baseline, tooling gaps)\n- Scope creep on initiatives — doing too much, achieving nothing\n- External factors (market shift, competitor launch, regulation)"}, {"name": "Review & Scoring", "guidelines": "How progress will be measured and what happens after the cycle.\n\n### Scoring Method\n- 0.0 – 0.3: No meaningful progress\n- 0.4 – 0.6: Some progress but fell short\n- 0.7 – 0.8: Strong result (target for stretch goals)\n- 0.9 – 1.0: Fully achieved (goal may have been too easy)\n\n### Review Process\n- When is the end-of-cycle review?\n- What format (written self-assessment, team meeting, leadership review)?\n- How do learnings feed into next cycle's OKRs?\n\n### Retrospective Questions\n- What drove our best results?\n- What would we do differently?\n- Which OKRs should carry over, evolve, or be dropped?"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$OKRs$name$;

UPDATE public.prd_templates
SET description = $desc$Amazon-style press release from the book Working Backwards. Written in the format of a Press Release and FAQs after the successful launch of a product.$desc$,
    structure = $json${"instructions": "Write in the voice of a press release announcing a successfully launched product. The tone should be confident and newsworthy — written for a major publication, not an internal memo. Quotes should feel authentic and specific to the product. FAQs should address real concerns and tough questions, not softballs. Internal FAQs should surface genuine strategic, operational, and financial considerations.", "sections": [{"name": "Heading", "guidelines": "Name the product in a way the target customer will immediately understand.\n\n### Format\n- Product name: Clear, memorable, customer-facing name\n- Tagline: One sentence underneath that captures the core value proposition\n\nThe heading should work as a real headline — if a journalist saw it, they'd immediately grasp what's being announced."}, {"name": "Subheading", "guidelines": "One sentence that describes who the customer is and what benefit they gain.\n\n### Format\n[Product name] helps [target customer] [achieve specific benefit].\n\nThis should be benefit-focused (what the customer gets), not feature-focused (what the product does)."}, {"name": "Summary Paragraph", "guidelines": "The press release lead paragraph — sets the scene for the announcement.\n\n### Format\n[City], [Media Outlet] — [Proposed Launch Date] — [Company name] today announced [product name], a [brief description] that [key benefit for customers].\n\n### Guidelines\n- Write as if this is a real wire service press release\n- Lead with the most newsworthy aspect\n- Keep to 3-4 sentences maximum\n- Include a concrete detail that makes it tangible"}, {"name": "Problem Paragraph", "guidelines": "Describe the customer problem this product solves — written entirely from the customer's perspective.\n\n### Guidelines\n- Start with the customer, not the company: 'Today, [customers] struggle with...'\n- Use specific, vivid details about the pain (time wasted, money lost, frustration)\n- Quantify the problem where possible ('spend 4 hours per week manually...'\n- Make the reader feel the problem before they hear the solution\n- Do NOT mention your product in this paragraph"}, {"name": "Solution Paragraph(s)", "guidelines": "Describe how the product solves the problem — clearly and simply.\n### Guidelines\n- Lead with the outcome: 'With [product], [customers] can now [benefit]'\n- Explain how it works in plain language — no jargon\n- Highlight 2-3 key capabilities that directly address the problems above\n- For complex products, use multiple short paragraphs rather than one long one\n- Include a specific example or scenario that makes the solution concrete"}, {"name": "Quotes & Getting Started", "guidelines": "### Company Spokesperson Quote\nA quote from a leader at your company. It should:\n- Express the vision and why this matters\n- Sound like a real person talking, not marketing copy\n- Add context the press release paragraphs didn't cover\n\n### Customer Quote\nA hypothetical quote from a target customer. It should:\n- Describe the specific benefit they experienced\n- Reference a real use case or workflow\n- Sound authentic and enthusiastic without being over-the-top\n\n### Getting Started\nOne paragraph on how easy it is to start using the product. Include a call-to-action and link."}, {"name": "External FAQs", "guidelines": "Questions a customer, journalist, or analyst would ask after reading the press release.\n\n### Format\nQ: [Question]\nA: [Answer]\n\n### Example Questions\n- How much does it cost? / What's the pricing model?\n- How is this different from [competitor]?\n- When is it available? / How do I get access?\n- What data do you collect and how is it secured?\n- Does it integrate with [common tool]?\n\nAnswers should be direct and specific — no deflecting. If something is TBD, say so."}, {"name": "Internal FAQs", "guidelines": "Questions leadership, the board, or other teams would ask internally.\n\n### Format\nQ: [Question]\nA: [Answer]\n\n### Example Questions\n- Why is this the right problem to solve now?\n- What's the estimated revenue impact or market size?\n- How much will this cost to build and maintain?\n- What are the biggest risks? What could go wrong?\n- How does this fit into our broader product strategy?\n- What do we need from other teams to make this successful?\n\nBe honest and thorough — internal FAQs should surface the hard questions."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$PR FAQ$name$;

